let quickHoldFired=false,quickHoldTimer=null;
document.addEventListener('click',e=>{if(quickHoldFired&&e.target.closest('.quick-btn')){e.preventDefault();e.stopPropagation();quickHoldFired=false;return}const auth=e.target.closest('[data-auth]');if(auth){e.preventDefault();e.stopPropagation();if(auth.dataset.auth==='logout'){state.loggedIn=false;storage.set('aion-v08-auth','out');historyStack=[];settingsBar.classList.remove('open');header.classList.remove('settings-open');closeModal();navigate('home',{home:true});}else{state.loggedIn=true;storage.set('aion-v08-auth','in');historyStack=[];app.classList.remove('logged-out');navigate('home',{home:true});}return}const attention=e.target.closest('[data-attention-order]');if(attention){e.preventDefault();const orderId=attention.dataset.attentionOrder,device=attention.dataset.attentionDevice,target=attention.dataset.attentionTarget;navigate(target,{params:{orderId,device}});return}const why=e.target.closest('[data-why]');if(why){e.preventDefault();e.stopPropagation();openModal(`<h3>Почему?</h3><p>Заказ №125 ждёт согласования дольше обычного. Факт: диагностика завершена в 09:10. Источник: журнал заказа. Рекомендация AION: связаться с клиентом. AION не изменяет статус.</p><div class="inline-actions"><button class="small-btn" data-close-modal>Закрыть</button></div>`);return}const proof=e.target.closest('[data-proof]');if(proof){e.preventDefault();e.stopPropagation();openModal(`<h3>Proof Chain</h3><p>Диагностика завершена · 09:10 · Петров. Источник: журнал заказа. Следующее состояние выводится только из подтверждённых событий.</p><div class="inline-actions"><button class="small-btn" data-close-modal>Закрыть</button></div>`);return}const debt=e.target.closest('[data-debt]');if(debt){openModal(`<h3>Выдача в долг — исключение</h3><p><b>Это НЕ оплата.</b> В production такой сценарий требует отдельного разрешения, основания, автора, времени и evidence. В этом v0.8 он только объясняется и не обходится одним toggle.</p><div class="inline-actions"><button class="small-btn" data-close-modal>Понятно</button></div>`);return}if(e.target.closest('[data-close-modal]')){closeModal();return}const pin=e.target.closest('[data-pin]');if(pin){e.preventDefault();e.stopPropagation();const id=pin.dataset.pin,wasPinned=state.pinned.includes(id);state.pinned=wasPinned?state.pinned.filter(x=>x!==id):[...state.pinned,id].slice(-4);savePinned();showToast(wasPinned?'Убрано с Главной':'Добавлено на Главную');return}const tool=e.target.closest('[data-tool]');if(tool){navigate(tool.dataset.tool);return}const cap=e.target.closest('[data-capture]');if(cap){e.preventDefault();e.stopPropagation();navigate('capture',{params:{mode:cap.dataset.capture}});return}const g=e.target.closest('[data-go]');if(g){e.preventDefault();navigate(g.dataset.go);return}const n=e.target.closest('[data-new]');if(n){newRepair(n.dataset.new);return}const f=e.target.closest('[data-fill]');if(f){fillContext(f.dataset.fill);return}const conf=e.target.closest('[data-confirm-match]');if(conf){navigate(conf.dataset.confirmMatch);return}const src=e.target.closest('[data-source]');if(src){e.preventDefault();if(src.dataset.source==='text')$('#searchInput')?.focus();return}const s=e.target.closest('[data-search]');if(s){const q=($('#searchInput')?.value||'').trim();if(/125|Иван/.test(q)){showToast('Однозначный заказ найден');setTimeout(()=>navigate('order'),180)}else navigate('capture',{params:{mode:'context'}});return}const set=e.target.closest('[data-set]');if(set){const a=set.dataset.set;if(a==='minus')applyScale(scaleIndex-1);if(a==='plus')applyScale(scaleIndex+1);if(a==='reset')applyScale(2);if(a==='theme')app.classList.toggle('light');if(a==='workspace')navigate('settings');if(a==='account')openModal(`<h3>Аккаунт</h3><p><b>Иван</b><br>Сотрудник / Мастер</p><div class="inline-actions"><button class="small-btn" data-auth="logout">Выйти</button><button class="small-btn ghost" data-close-modal>Закрыть</button></div>`);return}const ws=e.target.closest('[data-workspace]');if(ws){state.workspace=ws.dataset.workspace;storage.set('aion-v08-workspace',state.workspace);applyWorkspace();rerender('settings');return}const doc=e.target.closest('[data-doc]');if(doc){if(doc.dataset.doc==='open'){openModal(`<h3>${doc.dataset.docTitle||'Документ'}</h3><div class="doc-preview"><b>Заказ №125 · iPhone 13</b><p>${doc.dataset.docSub||'Симулированный документ AION Service CRM'}</p><div class="doc-preview-sheet">AION Service CRM<br><br>Клиент: Иван Иванов<br>Устройство: iPhone 13<br>Заказ: №125<br><br>Это демонстрационный preview документа.</div></div><div class="inline-actions"><button class="small-btn" data-close-modal>Закрыть</button></div>`)}else showToast(doc.dataset.doc==='print'?'Печать доступна в capability-режиме':'Документ подготовлен к скачиванию');return}});
headLeft.addEventListener('click',e=>{const b=e.target.closest('[data-head]');if(!b)return;if(b.dataset.head==='menu')toggleToolbelt();if(b.dataset.head==='back')goBack();if(b.dataset.head==='home')goHome()});gearBtn.addEventListener('click',()=>{const open=!settingsBar.classList.contains('open');settingsBar.classList.toggle('open',open);header.classList.toggle('settings-open',open)});settingsBar.addEventListener('click',e=>{const b=e.target.closest('[data-set]');if(!b)return;e.preventDefault();e.stopPropagation();const a=b.dataset.set;if(a==='minus')applyScale(scaleIndex-1);if(a==='plus')applyScale(scaleIndex+1);if(a==='reset')applyScale(2);if(a==='theme')app.classList.toggle('light');if(a==='workspace')navigate('settings');if(a==='account')openModal(`<h3>Аккаунт</h3><p><b>Иван</b><br>Сотрудник / Мастер</p><div class="inline-actions"><button class="small-btn" data-auth="logout">Выйти</button><button class="small-btn ghost" data-close-modal>Закрыть</button></div>`)});$('#toolTrigger').addEventListener('click',()=>toggleToolbelt());shade.addEventListener('click',()=>{toggleToolbelt(false);setNextPanel(false);closeModal()});nextPeek.addEventListener('click',()=>setNextPanel(true));panelPrimary.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(panelPrimary.disabled)return;if(panelPrimary.dataset.action)act(panelPrimary.dataset.action);else if(panelPrimary.dataset.go)navigate(panelPrimary.dataset.go)});panelSecondary.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(panelSecondary.dataset.secondary==='Документы')navigate('documents');if(panelSecondary.dataset.secondary==='Есть проблема'){state.order.otkProblem=true;rerender('otk')}});
let panelTouch=null,bottomTouch=null;nextPeek.addEventListener('touchstart',e=>{const p=e.touches[0];bottomTouch={x:p.clientX,y:p.clientY}},{passive:true});nextPeek.addEventListener('touchend',e=>{if(!bottomTouch)return;const p=e.changedTouches[0];if(bottomTouch.y-p.clientY>24)setNextPanel(true);bottomTouch=null},{passive:true});nextPanel.addEventListener('touchstart',e=>{const p=e.touches[0];panelTouch={x:p.clientX,y:p.clientY}},{passive:true});nextPanel.addEventListener('touchend',e=>{if(!panelTouch)return;const p=e.changedTouches[0];if(p.clientY-panelTouch.y>38)setNextPanel(false);panelTouch=null},{passive:true});app.addEventListener('touchstart',e=>{const p=e.touches[0];if(p.clientY>innerHeight-72)bottomTouch={x:p.clientX,y:p.clientY}},{passive:true});app.addEventListener('touchend',e=>{if(bottomTouch){const p=e.changedTouches[0];if(bottomTouch.y-p.clientY>38)setNextPanel(true);bottomTouch=null}},{passive:true});stage.addEventListener('touchstart',e=>{const q=e.target.closest('.quick-btn');if(!q)return;quickHoldFired=false;quickHoldTimer=setTimeout(()=>{quickHoldFired=true;openModal(`<h3>Быстрый доступ</h3><p>Убрать «${q.textContent.trim()}» с Главной?</p><div class="inline-actions"><button class="small-btn warn" data-unpin-shortcut="${q.dataset.go}">Убрать с Главной</button><button class="small-btn ghost" data-close-modal>Отмена</button></div>`)},520)},{passive:true});stage.addEventListener('touchend',()=>{clearTimeout(quickHoldTimer)},{passive:true});stage.addEventListener('touchmove',()=>{clearTimeout(quickHoldTimer)},{passive:true});document.addEventListener('click',e=>{const u=e.target.closest('[data-unpin-shortcut]');if(!u)return;e.preventDefault();e.stopPropagation();state.pinned=state.pinned.filter(x=>x!==u.dataset.unpinShortcut);savePinned();closeModal();showToast('Убрано с Главной')});
let edgeStart=null;app.addEventListener('touchstart',e=>{const p=e.touches[0];edgeStart={x:p.clientX,y:p.clientY}},{passive:true});app.addEventListener('touchend',e=>{if(!edgeStart)return;const p=e.changedTouches[0],dx=p.clientX-edgeStart.x,dy=p.clientY-edgeStart.y;if(edgeStart.x<24&&dx>55&&Math.abs(dy)<50&&!toolbelt.classList.contains('open'))goBack();edgeStart=null},{passive:true});
const review=new URLSearchParams(location.search);const qScale=Number(review.get('scale'));if(levels.includes(qScale))scaleIndex=levels.indexOf(qScale);const qWorkspace=review.get('workspace');if(['graphite','slate','ocean'].includes(qWorkspace))state.workspace=qWorkspace;applyWorkspace();applyScale(scaleIndex);renderSettingsBar();renderToolbelt();app.classList.toggle('logged-out',!state.loggedIn);navigate(review.get('screen')&&screens[review.get('screen')]?review.get('screen'):'home',{home:true});if(review.get('rail')==='1')setTimeout(()=>toggleToolbelt(true),250);if(review.get('next')==='1')setTimeout(()=>setNextPanel(true),250);